#include <sstream>
#include <string>

int main() {
    std::istringstream entrada{"x 4\n7"};
    int valor = 0;
    if (!(entrada >> valor)) {
        if (entrada.bad()) {
            std::cout << "Fallo del flujo";
            return 0;
        }
        entrada.clear();
        std::string descartado;
        if (std::getline(entrada, descartado)) {
            std::cout << "Descartado:<" << descartado << ">\n";
        }
    }
    if (entrada >> valor) {
        std::cout << "Dato: " << valor;
    }
    return 0;
}

#include <iostream>
#include <sstream>
#include <string>

bool analizar_cantidad(const std::string& texto, int& resultado) {
    std::istringstream campos{texto};
    int cantidad = 0;
    if (!(campos >> cantidad)) {
        return false;
    }
    if (cantidad < 1 || cantidad > 12) {
        return false;
    }
    std::string extra;
    if (campos >> extra) {
        return false;
    }
    if (campos.bad() || !campos.eof()) {
        return false;
    }
    resultado = cantidad;
    return true;
}

int main() {
    int cantidad = 3;
    const bool aceptada = analizar_cantidad(" 8 ", cantidad);
    std::cout << aceptada << " " << cantidad;
    return 0;
}

